import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"Moto: Latent Motion Token as the Bridging Language for Learning Robot Manipulation from Videos","description":"","frontmatter":{"title":"Moto: Latent Motion Token as the Bridging Language for Learning Robot Manipulation from Videos","arxiv":"2412.04445","date":"2024-12-05","authors":"Yi Chen, Yuying Ge, Weiliang Tang, Yizhuo Li, Yixiao Ge, Mingyu Ding, Ying Shan, Xihui Liu","categories":"cs.RO, cs.AI, cs.CL, cs.CV, cs.LG","topics":"视频生成赋能具身智能, 潜运动 token, 自回归预训练","outline":[2,2]},"headers":[],"relativePath":"papers/2412.04445.md","filePath":"papers/2412.04445.md","lastUpdated":null}'),l={name:"papers/2412.04445.md"};function e(i,s,m,r,c,o){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="moto-latent-motion-token-as-the-bridging-language-for-learning-robot-manipulation-from-videos" tabindex="-1">Moto: Latent Motion Token as the Bridging Language for Learning Robot Manipulation from Videos <a class="header-anchor" href="#moto-latent-motion-token-as-the-bridging-language-for-learning-robot-manipulation-from-videos" aria-label="Permalink to &quot;Moto: Latent Motion Token as the Bridging Language for Learning Robot Manipulation from Videos&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2412.04445" target="_blank" rel="noreferrer">2412.04445</a></td></tr><tr><td><strong>提交日期</strong></td><td>2024-12-05（v4 2025-10-16，ICCV 2025）</td></tr><tr><td><strong>作者</strong></td><td>Yi Chen, Yuying Ge, Weiliang Tang, Yizhuo Li, Yixiao Ge, Mingyu Ding, Ying Shan, Xihui Liu（港大 / 腾讯 ARC Lab / 港中文 / UC Berkeley）</td></tr><tr><td><strong>分类</strong></td><td>cs.RO, cs.AI, cs.CL, cs.CV, cs.LG</td></tr><tr><td><strong>一句话</strong></td><td>用 VQ-VAE 把每两帧之间的视觉变化压成 8 个离散「运动 token」，让一个 98M 的 GPT 在视频上自回归预测<strong>整条</strong>运动 token 轨迹，再通过 co-fine-tuning 把这套运动语言接到真实动作头上。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/video-for-embodied-ai">视频生成赋能具身智能</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>arXiv abs 页当前指向 <strong>v4</strong>（2025-10-16），本文按 v4 全文撰写；v1 提交于 2024-12-05，论文被 ICCV 2025 接收。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>LLM 的成功配方是「在大语料上做下一 token 预测，再用少量数据微调」。机器人一直没能复制这个配方，缺的不是数据而是<strong>表示</strong>：视频是现成的「语料」，但用什么单位来做自回归？此前的视频预训练路线基本围绕像素或 patch token 展开，模型要花大量容量去建模与控制无关的纹理与背景。</p><p>Moto 提出的问题很锐利：给定视频这份语料，什么样的 token 才是对机器人有用的「词」？它的回答是：应该是<strong>运动</strong>——运动与低层动作直接相关，且是硬件无关的，因此可以在人手与机械臂之间共享。这个定位带来的直接好处在实验里能看到：一个只有 98M 参数、预训练时完全没见过动作标签、部署时只用一路静态 RGB 的模型，在 SIMPLER 上的总体成功率与 55B 的 RT-2-X 相当。如果表示选对了，规模就不是唯一杠杆。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>VLA 与生成式预训练</strong>：一类做法是从图文预训练的 VLM 微调出策略（RT-2、OpenVLA），另一类是在多样机器人数据上训通才模型（Octo、RT-X）。它们要么继承的是静态的图文知识，要么受限于带标注机器人数据的规模。GR-1 一类工作做视频预训练，但预测的是像素/patch 级内容，帧级细节占据了大部分建模预算。</p><p><strong>潜动作</strong>：Genie 从大规模视频中无监督学习潜动作以驱动 2D 游戏模拟器；LAPO 局限于游戏；DynaMo 关注视觉表征学习。与本文同期的 LAPA（<a href="/notes/papers/2410.11758">2410.11758</a>）预训练模型预测<strong>一步</strong>未来潜动作，IGOR 把潜动作当作中间目标。作者给自己的划界是：Moto-GPT 自回归地预测<strong>一整条</strong>未来视频片段的潜运动 token 轨迹，而不是单步，这更贴近「序列建模」的本意；此外本文对每个训练阶段都做了单独验证。</p><p>值得说明前人为什么没走到这一步。把视觉变化离散化并不新鲜（VQ-VAE 2017 年就有），难点在于让离散码<strong>恰好</strong>落在「运动」这一语义层级上：码本太大会退化成帧压缩，太小则丢失可执行性；解码器若能看到太多信息，码就会被旁路。本文的做法是把量化嵌入经 MLP 压成<strong>单个</strong> token 再加到每个输入 patch 上，用极窄的瓶颈强制码只承载帧间变化。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>从 2024 年中的已知出发：视频预训练确实有效，但有效的原因不清楚；同时期证据显示帧级重建目标对控制的边际收益递减。一个自然的假设是——人类学新技能时看的是「状态怎么变」，不是「像素长什么样」，那么预训练目标也应该对齐到变化量。</p><p>要把变化量做成「语言」，需要三个性质：离散（便于 GPT 建模）、紧凑（便于长序列自回归）、跨本体一致（便于从人类视频迁移）。VQ-VAE 同时给出前两点；第三点则要靠瓶颈设计——若码里还残留外观信息，人手与机械臂就不可能共享同一个码。于是有了「解码器只拿 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6389em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathnormal">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">−</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span></span></span></span> 的 patch 嵌入 + 一个压缩后的条件 token」这种极端设计。</p><p>接着是一个容易被忽略的实际问题：预训练与部署的接口。若部署时必须先生成运动 token 再出动作，推理会变慢，而且动作质量被 token 预测质量绑住。作者的处理是 co-fine-tuning + 50% 注意力随机掩码：训练时让 action query 有一半概率看不到运动 token，这样部署时可以用 padding 占位、完全跳过 token 生成。这一步是为效率服务的，但它也在事实上削弱了「桥接语言」在推理期的作用（见 §9）。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>把视频压成「运动的词表」而不是「画面的词表」，模型的建模预算就全花在与动作同构的量上；因为这个词表只描述变化、不描述外观，同一个码在人手视频和机械臂视频里指向同一件事，于是人类视频可以直接当作机器人的预训练语料。之后的动作学习退化成一个简单的对齐问题：把抽象的运动意图翻译成具体的关节指令，这一步所需的数据量远小于从零学策略。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以 CALVIN 中「把粉色方块推到右边」为例：</p><ol><li><strong>潜运动 tokenizer（无监督）</strong>：对视频先按一定倍率下采样以保证帧间有明显差异。M-Former（多层 transformer）吃冻结 ViT 提取的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6389em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathnormal">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">−</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 的最后一层 patch 特征，外加 8 个可学习 query，经自注意力交互后由 VQ 码本（词表大小 128）量化成 8 个离散运动 token。解码侧是 ViT Decoder：输入 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6389em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathnormal">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">−</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span></span></span></span> 的线性嵌入 patch，另有一个 MLP 把 8 个量化嵌入拼接后投影成<strong>1 个</strong> token 加到每个 patch 嵌入上，重建 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 的像素。损失是标准 VQ-VAE 三项，重建用 MSE。训练完成后 tokenizer 冻结。</li><li><strong>Moto-GPT 预训练</strong>：对视频片段 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord"><span class="mord mathnormal">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">]</span></span></span></span> 的每一对相邻帧取一组 8 个 token，按时间拼成序列。GPT 式 transformer（98M）以冻结 T5 的语言特征与冻结 ViT 的首帧视觉特征作为前缀 prompt，做下一 token 预测。此阶段完全不需要动作标签。</li><li><strong>Co-fine-tuning</strong>：在每个时间步的运动 token chunk 之后插入 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> 个 action query token（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> = 两帧之间的机器人动作数）。因果掩码沿用预训练设定，且<strong>运动 token 不注意 action query</strong>；同时随机屏蔽 50% 的「action query → 运动 token」注意力。MLP 动作头把 action query 的隐状态投影到动作空间，连续量（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Δ</span><span class="mord mathnormal">x</span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord">Δ</span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span></span></span></span>）用 Smooth-L1、二值夹爪用 BCE。总损失 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1076em;">f</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">m</span><span class="mord mathnormal mtight">o</span><span class="mord mathnormal mtight">t</span><span class="mord mathnormal mtight">i</span><span class="mord mathnormal mtight">o</span><span class="mord mathnormal mtight">n</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">a</span><span class="mord mathnormal mtight">c</span><span class="mord mathnormal mtight">t</span><span class="mord mathnormal mtight">i</span><span class="mord mathnormal mtight">o</span><span class="mord mathnormal mtight">n</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，即保留运动 token 预测目标以免遗忘先验。</li><li><strong>部署</strong>：可以直接查询动作——用 padding token 占位替代运动 token，并屏蔽 action query 对这些占位符的注意力，从而跳过 token 生成。</li><li><strong>附带能力</strong>：把一段演示视频抽出的 token 序列送进 tokenizer 解码器，配上<strong>不同的</strong>首帧，可以在新场景「重演」原动作（视频模仿生成）；也可以用 Moto-GPT 的输出似然给轨迹打分。</li></ol><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>预训练目标是条件自回归似然：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">m</span><span class="mord mathnormal mtight">o</span><span class="mord mathnormal mtight">t</span><span class="mord mathnormal mtight">i</span><span class="mord mathnormal mtight">o</span><span class="mord mathnormal mtight">n</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:3.106em;vertical-align:-1.2777em;"></span><span class="mord">−</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.8283em;"><span style="top:-1.8723em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">M</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2777em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord mathnormal">m</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord"><span class="mord boldsymbol" style="margin-right:0.0088em;">l</span></span></span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord"><span class="mord boldsymbol" style="margin-right:0.037em;">v</span></span></span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord"><span class="mord"><span class="mord boldsymbol">m</span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mrel mtight">&lt;</span><span class="mord mathnormal mtight">i</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1774em;"><span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">)</span></span><span class="mpunct">,</span></span></span></span></span></p><p>其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord"><span class="mord"><span class="mord boldsymbol" style="margin-right:0.0088em;">l</span></span></span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4444em;"></span><span class="mord"><span class="mord"><span class="mord boldsymbol" style="margin-right:0.037em;">v</span></span></span></span></span></span> 分别是冻结 T5 与 ViT 给出的语言与首帧视觉特征，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">m</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6595em;"></span><span class="mord mathnormal">i</span></span></span></span> 个运动 token。微调阶段的联合目标为</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1076em;">f</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">m</span><span class="mord mathnormal mtight">o</span><span class="mord mathnormal mtight">t</span><span class="mord mathnormal mtight">i</span><span class="mord mathnormal mtight">o</span><span class="mord mathnormal mtight">n</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">a</span><span class="mord mathnormal mtight">c</span><span class="mord mathnormal mtight">t</span><span class="mord mathnormal mtight">i</span><span class="mord mathnormal mtight">o</span><span class="mord mathnormal mtight">n</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">a</span><span class="mord mathnormal mtight">c</span><span class="mord mathnormal mtight">t</span><span class="mord mathnormal mtight">i</span><span class="mord mathnormal mtight">o</span><span class="mord mathnormal mtight">n</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathcal">L</span><span class="mopen">(</span><span class="mord">Δ</span><span class="mord mathnormal">x</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathcal">L</span><span class="mopen">(</span><span class="mord">Δ</span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathcal">L</span><span class="mopen">(</span><span class="mord">Δ</span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mord mathnormal">i</span><span class="mord mathnormal">p</span><span class="mclose">)</span><span class="mord">.</span></span></span></span></span></p><p>这里最值得解释的是<strong>信息瓶颈</strong>为什么必须窄到「1 个 token」。设解码器为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">D</span></span></span></span>，若它能同时访问 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6389em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathnormal">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">−</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span></span></span></span> 的完整 patch 与一个高维条件向量 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">c</span></span></span></span>，那么最小化重建误差有两条路径：从 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6389em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathnormal">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">−</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span></span></span></span> 推 + 用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">c</span></span></span></span> 补差异，或者直接把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 的信息塞进 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">c</span></span></span></span>。后者对重建更省力，却会让 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">c</span></span></span></span> 变成「下一帧的压缩表示」而不是「运动」。把 8 个量化嵌入压成单个加性 token，等于把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">c</span></span></span></span> 的容量压到远低于一张图所需的比特数，逼迫模型走第一条路径。这一设计与目标函数一起，才使得「同一个码在不同本体上表示同一动作」（Fig. 4 的列一致性）成为可能。</p><p>似然还有第二个用途：把一段轨迹视频转成 token 序列后，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span></span></span></span> 可以直接当作合理性打分。作者在 CALVIN 收集了 98 组三元组（成功 / 失败 / 随机策略，同一初始状态），逐步平均对数似然能清晰区分三类，提示它可以充当无动作标注的奖励信号。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一（可解释性）：运动 token 真的表示运动吗？</strong> 定性上，同一组 token 配不同首帧产生一致的运动方向与幅度（列一致），不同 token 配同一首帧产生可区分的运动（行区分）。定量上用视频分类代理：以首帧 ViT patch 特征 + 后续 7 组运动 token 预测 CALVIN 34 类任务标签，准确率 0.797；作为对照，用全部 8 帧的 ViT 特征是 0.828，只用首帧是 0.292（首帧重复 8 次 0.283）。即：每帧特征从 196 个压到 8 个 token，语义几乎不损失。</p><p><strong>问题二（运动先验）：预训练学到了什么？</strong> 给不同语言指令，Moto-GPT 能自回归产生对应的 token 序列并解码成合理的视频轨迹；输出似然能区分成功/失败/随机三类轨迹。</p><p><strong>问题三（策略性能）：</strong> SIMPLER（Google 机器人，抓可乐罐 / 移到附近 / 开关抽屉）总体成功率：Moto 0.614，RT-2-X 0.607，RT-1-X 0.534，OpenVLA（微调后）0.349，Octo-Base 0.169，去掉运动 token 从零训的 Moto w/o Motion Token 0.480。逐项看并非全胜：抓可乐罐 0.740 明显领先（RT-1-X 0.567），移到附近 0.604 输给 RT-2-X 的 0.779，抽屉平均 0.431 明显输给 RT-1-X 的 0.597（其中「开」只有 0.130，RT-1-X 是 0.296）。CALVIN ABC→D：Moto 平均长度 3.10，仅用静态 RGB；GR-1 3.06，用静态 + 夹爪 RGB + 本体感知；从零训的对照 2.14。逐档看，Moto 的第 1–3 档更高（0.897/0.729/0.601 对 0.854/0.712/0.596），第 4、5 档反而更低（0.484/0.386 对 0.497/0.401）。</p><p><strong>问题四（真机）：</strong> FANUC LR Mate 200iD，三个任务（抓放香蕉、合笔记本、拆卸），每任务 30 条演示、测 10 次。平均成功率从 23.33% 提升到 60%；加视觉干扰物与更换物体外观后分别提升 20% 与 30%。</p><p><strong>问题五（数据效率与人类视频）：</strong> 用不同比例的带标注数据微调，Moto 全程领先从零训版本，1% 标注数据时 52.5% 对 0%。加入 SSV2 的 10.5 万条人类视频（与 10.9 万条 OXE 机器人视频一起训 tokenizer 与 GPT）后，SIMPLER 的 Move Near 进一步提升。</p><p><strong>问题六（微调方式消融）：</strong> Moto-IML（微调时去掉运动 token 损失）与 Moto-DM（输入里完全不含运动 token）都优于从零训练，但都低于完整的 co-fine-tuning，说明保留 token 在序列中并让 action query 通过注意力读取是有价值的。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：把视频压成「运动 token」而非「画面 token」，98M 的 GPT 在 SIMPLER 上就能与 55B 的 RT-2-X 打平（0.614 对 0.607）。瓶颈设计是关键：8 个量化嵌入被压成 1 个加性条件 token，逼迫码只承载帧间变化，从而在人手与机械臂之间通用。CALVIN ABC→D 上只用一路静态 RGB 拿到 3.10，与用三种输入的 GR-1 的 3.06 相当，但优势集中在前 3 档、第 4/5 档反而略低。数据效率是最扎实的结论：1% 标注数据时 52.5% 对从零训练的 0%。预训练模型的输出似然可以区分成功/失败/随机轨迹，提示了一个无需动作标签的奖励信号。</p><p><strong>3 句话版</strong>：运动而非像素才是适合机器人的自回归单位，因为它与低层动作同构且硬件无关。窄瓶颈的 VQ-VAE 让这套 token 在人-机之间共享，人类视频因此可以直接当预训练语料。它的收益主要体现在数据稀缺与短程任务上，长链后段并未超过同期方法。</p><p><strong>1 句话版</strong>：用 128 词的「运动语言」预训练一个百兆参数的 GPT，就能顶得上百亿参数 VLA 的多数场景表现。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最要命的一条是：<strong>「桥接语言」在部署时确实被使用</strong>。论文的全部叙事建立在「运动 token 是连接视频预训练与机器人控制的中介」之上，但 §3.4 明确写道，为提升推理效率，训练时随机屏蔽 50% 的 action query 到运动 token 的注意力，从而在部署时可以用 padding 占位、<strong>完全跳过运动 token 的生成</strong>。一旦如此，推理路径里就没有任何运动 token，剩下的只有「一组被运动预测任务训练过的 GPT 权重」。那么方法的贡献就应重述为「一种有效的预训练目标」，而不是「一种可执行的中间语言」。</p><p>论文自己的消融给出了这条风险的直接证据：Moto-DM——输入里完全不含运动 token 的变体——依然明显优于从零训练。这说明相当一部分增益来自权重而非 token 流。作者的解释是完整版更好，因此 token 有额外价值；但缺的对照恰恰是最关键的那一格：<strong>部署时用占位符跳过 token 生成的完整 Moto，与逐步生成 token 的完整 Moto，成功率相差多少</strong>。若二者持平，那么「语言」在推理期是惰性的；若差距明显，则论文的效率卖点需要打折。这一格在全文中从未出现。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，且不需要重跑预训练：</p><ul><li>取作者开源的 Moto checkpoint 与 CALVIN ABC→D 评测脚本，建立复现基线（目标平均长度约 3.10）。</li><li>三种推理配置，权重完全相同：(a) 自回归先生成运动 token、再让 action query 注意它们；(b) 用 padding 占位、屏蔽注意力，直接出动作（论文声称的高效部署路径）；(c) 用<strong>随机采样自码本</strong>的假 token 替换生成的 token，其余不变。</li><li>度量：CALVIN 平均完成长度，以及每步推理耗时。</li><li>判据：若 (a) 与 (b) 差距小于 0.1，说明运动 token 在推理期基本不起作用，「桥接语言」应重述为「预训练目标」；若 (a) 明显优于 (b) 且 (c) 明显劣于 (b)，则 token 内容确实被策略读取，论文的机制解释成立。(c) 相对 (b) 的落差还能直接量化「token 的信息含量」与「token 位置的占位效应」之差。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>替代解释：<strong>总体成功率的领先是任务构成的产物，而非能力的普遍提升</strong>。SIMPLER 上 Moto 的 Overall 0.614 只比 RT-2-X 的 0.607 高 0.007，而逐项拆开方向并不一致：抓可乐罐 0.740 大幅领先，Move Near 0.604 明显落后 RT-2-X 的 0.779，开关抽屉平均 0.431 大幅落后 RT-1-X 的 0.597（「开抽屉」只有 0.130，甚至低于自家从零训练版本在「关抽屉」上的 0.796 所展示的水平）。CALVIN 上同样如此：3.10 对 3.06 的优势完全来自前 3 档，第 4 档 0.484 与第 5 档 0.386 都低于 GR-1 的 0.497 与 0.401——而后两档恰恰是长时程能力的直接度量。换句话说，Moto 更擅长「起步阶段做对」，在链条后段的鲁棒性上并没有优势。</p><p>设计一个能证伪的实验：把 SIMPLER 与 CALVIN 的任务按「运动是否需要精确接触时序」分成两组（抓放/推移 vs 开关抽屉、按压、拧动），在两组上分别报告 Moto 与基线的成功率，并做配对显著性检验。可预测的结果是：在接触时序敏感的一组上 Moto 系统性落后，因为运动 token 是在<strong>下采样后的</strong>帧对上定义的，其时间分辨率天然低于夹爪开合事件的时间尺度；而在位移主导的一组上 Moto 领先。若这一模式成立，本文的正确表述应当是「运动 token 是一种位移语义的高效表示」，而非「适用于机器人操作的通用桥接语言」，同时也解释了为什么真机三个任务（抓放香蕉、合笔记本、拆卸）里增益最大的是位移主导的那些。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>(a) 驱动局限</strong>：论文把预训练模型的对数似然当作一个附带发现展示（Fig. 7 能区分成功/失败/随机轨迹），随后就没有再用它。而这恰恰是全文最独特的产物：一个<strong>无需动作标签、无需人工奖励标注</strong>的轨迹合理性打分器。与此同时，方法在长链后段的劣势说明策略本身缺乏「察觉自己走偏」的机制。两件事正好互补。</p><p><strong>(b) 新的 framing 与可借的工具</strong>：把 Moto-GPT 从「策略的初始化」重新定位成<strong>过程级验证器</strong>（process verifier）。LLM 领域已经把「结果奖励模型 vs 过程奖励模型」这一区分做得很透：逐步打分比只看最终结果的信号密度高得多，且可以驱动测试时搜索。这里的对应物是：把候选动作块执行后的观测序列转成运动 token，用 Moto-GPT 逐步似然打分，选择似然最高的分支；或在离线数据筛选中剔除低似然片段。可借的工具还有能量模型的重排序、以及 RL 中用学习到的模型做短程 rollout 打分（Dyna 式）。</p><p><strong>(c) 第一个实验</strong>：不必改动策略。在 CALVIN ABC→D 上，取任意一个现成策略（包括 Moto 自己），每步采样 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">8</span></span></span></span> 个动作块，在仿真里各推进 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> 步，把得到的观测对转成运动 token，用冻结的 Moto-GPT 计算平均对数似然并选最高者。度量三点：平均完成长度相对无搜索基线的提升；提升是否集中在第 4/5 档（若是，验证了「似然可补长程鲁棒性」）；以及似然与真实成功之间的 AUROC。若 AUROC 明显高于 0.5 而平均长度提升有限，说明打分器有信息但搜索空间选错了，下一步应转向离线数据筛选而非在线搜索——无论哪种结果，都把研究问题从「什么表示适合预训练」推进到「预训练模型除了做初始化还能做什么」。</p>',51)])])}const d=a(l,[["render",e]]);export{g as __pageData,d as default};
